from math import gcd
from functools import reduce

def lcm(a, b):
    return abs(a*b) // gcd(a, b) if a and b else 0

def list_lcm(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

def list_gcd(numbers):
    if not numbers:
        return 0 # Or handle based on definition, but since a_i are positive, we expect positive GCD
    return reduce(gcd, numbers)

def count_good_partitions(sequence):
    n = len(sequence)
    count = 0
    for k in range(1, n):
        A_k = sequence[:k]
        B_k = sequence[k:]
        L_k = list_lcm(A_k)
        G_k = list_gcd(B_k)
        if L_k == G_k:
            count += 1
    return count

# Check n=3: (1, 2, 3)
print(f"n=3 (1, 2, 3): {count_good_partitions([1, 2, 3])}")

# Check n=4: (1, 2, 4, 6)
print(f"n=4 (1, 2, 4, 6): {count_good_partitions([1, 2, 4, 6])}")

# Check n=5: (1, 2, 4, 6, 10)
print(f"n=5 (1, 2, 4, 6, 10): {count_good_partitions([1, 2, 4, 6, 10])}")

